import (
    "fmt"
    "net"
    "sync"
    "time"
)

func scan(host string, port int, wg *sync.WaitGroup) {
    defer wg.Done()
    addr := fmt.Sprintf("%s:%d", host, port)
    conn, err := net.DialTimeout("tcp", addr, 500*time.Millisecond)
    if err != nil { return }
    conn.Close()
    fmt.Printf("[+] %s open\n", addr)
}

