class Reader:
    def __init__(self, data):
        self.data = data
        self.off = 0
    def u32(self):
        v = struct.unpack_from('<I', self.data, self.off)[0]
        self.off += 4
        return v
    def cstr(self):
        end = self.data.index(b'\x00', self.off)
        s = self.data[self.off:end].decode('utf-8', 'replace')
        self.off = end + 1
        return s

int parse(const char *buf, size_t len) {
    if (len < 4) return 0;
    if (memcmp(buf, "MYFT", 4) != 0) return 0;
    unsigned int n = buf[4];
    char *out = malloc(16);
    memcpy(out, buf + 5, n);   // no bounds check
    free(out);
    return 1;
}

